 import { gsap } from 'gsap';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { color, mix, smoothstep, uv } from 'three/tsl';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors || config.colors || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const { Group, PlaneGeometry, BoxGeometry, Mesh, DirectionalLight, PointLight } = THREE;
  const group = new Group();
  group.name = config.id || 'journal-card-3';

  const surfaceCol = new THREE.Color(colors.surface);
  const inkCol = new THREE.Color(colors.ink);
  const paperCol = new THREE.Color(colors.paper);
  const accentCol = new THREE.Color(colors.accent);

  // Stage backdrop
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({
    colorNode: mix(
      color(surfaceCol),
      color(inkCol),
      smoothstep(0.15, 0.85, uv().y)
    ),
    side: THREE.DoubleSide
  });
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // Local lighting for the extruded backing.
  const keyLight = new DirectionalLight(paperCol, 0.9);
  keyLight.position.set(3, 4, 5);
  group.add(keyLight);

  const rimLight = new PointLight(accentCol, 0, 7);
  rimLight.position.set(-1.5, 1, 2);
  group.add(rimLight);

  // Card plane
  const cardW = 2.4;
  const cardH = 1.5;

  const cardGeo = new PlaneGeometry(cardW, cardH);
  const cardMat = new MeshBasicNodeMaterial({
    color: '#333333',
    transparent: true,
    depthWrite: false
  });
  const card = new Mesh(cardGeo, cardMat);
  group.add(card);

  // Accent edge plane behind the isolated texture
  const edgeGeo = new PlaneGeometry(cardW * 1.08, cardH * 1.08);
  const edgeMat = new MeshBasicNodeMaterial({
    color: accentCol,
    transparent: true,
    opacity: 0,
    depthWrite: false
  });
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.z = -0.04;
  group.add(edge);

  // Extruded backing panel
  const backGeo = new BoxGeometry(cardW * 1.1, cardH * 1.1, 0.05);
  const backMat = new MeshBasicNodeMaterial({
    color: surfaceCol,
    transparent: true,
    opacity: 0.95
  });
  const backing = new Mesh(backGeo, backMat);
  backing.position.z = -0.05;
  group.add(backing);

  // Stock badge
  const badgeGroup = new Group();
  const tagW = 0.9;
  const tagH = 0.22;
  const tagGeo = new BoxGeometry(tagW, tagH, 0.02);
  const tagMat = new MeshBasicNodeMaterial({
    color: surfaceCol,
    transparent: true,
    opacity: 0.92
  });
  const tagBg = new Mesh(tagGeo, tagMat);
  badgeGroup.add(tagBg);

  let badgeText = ctx.fontAtlas.createText('IN STOCK', {
    fontSize: 0.09,
    color: colors.paper,
    align: 'center'
  });
  badgeText.position.z = 0.015;
  badgeGroup.add(badgeText);

  badgeGroup.position.set(0.85, 0.65, 0.05);
  group.add(badgeGroup);

  // Async texture load
  let loadedTex = null;
  let texLoaded = false;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (!group.userData.isDisposed) {
        tex.colorSpace = THREE.SRGBColorSpace;
        tex.minFilter = THREE.LinearFilter;
        tex.magFilter = THREE.LinearFilter;
        loadedTex = tex;
        texLoaded = true;
        cardMat.map = tex;
        cardMat.needsUpdate = true;
      }
    });
  }

  // Badge update helper
  function setInStock(value) {
    if (!badgeText) return;
    badgeGroup.remove(badgeText);
    badgeText = ctx.fontAtlas.createText(value ? 'IN STOCK' : 'BACKORDER', {
      fontSize: 0.09,
      color: value ? colors.paper : colors.accent,
      align: 'center'
    });
    badgeText.position.z = 0.015;
    badgeGroup.add(badgeText);
  }

  group.userData.stockBadge = {
    inStock: true,
    set value(v) {
      this.inStock = Boolean(v);
      setInStock(this.inStock);
    },
    get value() {
      return this.inStock;
    }
  };

  // Motion timelines
  let disposed = false;
  const hoverTl = gsap.timeline({ paused: true });
  hoverTl
    .to(group.position, {
      y: 0.15,
      duration: 0.5,
      ease: 'power2.out'
    }, 0)
    .to(edgeMat, {
      opacity: 0.85,
      duration: 0.35,
      ease: 'power2.out'
    }, 0)
    .to(rimLight, {
      intensity: 0.7,
      duration: 0.4,
      ease: 'power2.out'
    }, 0);

  const pressTl = gsap.timeline({ paused: true });
  pressTl
    .to(group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'power1.out',
      yoyo: true,
      repeat: 1
    });

  // Interactions
  group.userData.handlers = {
    hoverEnter() {
      hoverTl.play();
    },
    hoverLeave() {
      hoverTl.reverse();
    },
    click() {
      pressTl.restart();
      ctx.emit('hub-journal.select', { nodeId: config.id });
    }
  };

  group.userData.cleanup = function cleanup() {
    disposed = true;
    group.userData.isDisposed = true;

    hoverTl.kill();
    pressTl.kill();

    group.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => {
            if (m.map) m.map.dispose();
            m.dispose();
          });
        } else {
          if (obj.material.map) obj.material.map.dispose();
          obj.material.dispose();
        }
      }
    });

    if (loadedTex) loadedTex.dispose();

    while (group.children.length) {
      group.remove(group.children[0]);
    }
  };

  return group;
}
